import { readAccountResponse } from './storage.js';
/** FieldShift introduction and entry screen. */
const copy={en:{title:'FieldShift',body:'Turn Earth observations and your own field records into clearer farming decisions. Explore local weather, water demand, soil conditions, resilient crop rotations and profit scenarios for the exact land you choose.',enter:'Enter FieldShift',replay:'Replay introduction',replayBody:'See the FieldShift introduction again.'},fr:{title:'FieldShift',body:'Transformez les observations de la Terre et vos propres relevés de terrain en décisions agricoles plus claires. Explorez la météo locale, les besoins en eau, l’état du sol, les rotations résilientes et les scénarios de bénéfices pour la terre choisie.',enter:'Entrer dans FieldShift',replay:'Revoir l’introduction',replayBody:'Revoir l’introduction de FieldShift.'},ar:{title:'فيلد شيفت',body:'حوّل رصد الأرض وسجلات حقلك إلى قرارات زراعية أوضح. استكشف الطقس المحلي واحتياجات المياه وحالة التربة وتناوب المحاصيل المرن وسيناريوهات الربح للأرض التي تختارها.',enter:'دخول فيلد شيفت',replay:'إعادة المقدمة',replayBody:'شاهد مقدمة فيلد شيفت مرة أخرى.'}};

export function initIntro({language='en'}={}){
  let current=copy[language]?language:'en',zoomTimer,revealTimer,hideTimer;
  const overlay=document.createElement('section');overlay.className='fieldshift-intro earth-intro';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','FieldShift introduction');
  overlay.innerHTML='<div class="earth-landscape" aria-hidden="true"></div><div class="earth-intro-copy"><img class="earth-intro-logo" src="assets/logo-new.png" alt="FieldShift logo"><h1></h1><p></p><button type="button" class="earth-intro-enter"></button></div>';document.body.append(overlay);
  const enter=overlay.querySelector('.earth-intro-enter');
  const auth=document.createElement('div');auth.className='intro-auth';auth.hidden=true;auth.innerHTML='<form class="intro-auth-form"><label>Username<input name="username" autocomplete="username" minlength="3" maxlength="254" required></label><label>Password <span class="intro-password-field"><input name="password" type="password" autocomplete="current-password" minlength="3" maxlength="128" required><button type="button" class="intro-show-password">Show</button></span></label><p class="intro-auth-error" role="alert"></p><button class="earth-intro-enter" type="submit">Log in</button></form><button class="earth-intro-account intro-switch" type="button">Create an account</button><button class="earth-intro-account intro-guest" type="button">Continue as guest</button>';overlay.querySelector('.earth-intro-copy').append(auth);
  const panel=document.querySelector('.settings-panel'),row=document.createElement('div');row.className='setting-item intro-replay-setting';row.innerHTML='<div><b></b><p></p></div><button type="button" class="button secondary small"></button>';panel.append(row);
  const apply=()=>{const words=copy[current];overlay.querySelector('h1').textContent=words.title;overlay.querySelector('p').textContent=words.body;enter.textContent=words.enter;row.querySelector('b').textContent=words.replay;row.querySelector('p').textContent=words.replayBody;row.querySelector('button').textContent=words.replay;};
  const clear=()=>{clearTimeout(zoomTimer);clearTimeout(revealTimer);clearTimeout(hideTimer);};
  const close=()=>{clear();sessionStorage.setItem('fieldshift.intro.skip-auto','1');overlay.classList.add('leaving');document.body.classList.remove('intro-open','intro-pending');hideTimer=setTimeout(()=>overlay.hidden=true,380);document.querySelector('.topbar-field')?.focus();window.dispatchEvent(new CustomEvent('fieldshift:intro:closed'));};
  const open=()=>{clear();auth.hidden=true;enter.hidden=false;overlay.querySelector('.earth-intro-copy > p').hidden=false;overlay.hidden=false;overlay.classList.remove('leaving','zooming','revealed');document.body.classList.add('intro-open','intro-pending');enter.disabled=false;void overlay.offsetWidth;overlay.classList.add('revealed');enter.focus();};
  let mode='login';const form=auth.querySelector('form'),error=auth.querySelector('.intro-auth-error');
  enter.onclick=()=>{if(window.__fieldshiftStorage?.session?.user){close();return;}overlay.querySelector('.earth-intro-copy > p').hidden=true;enter.hidden=true;auth.hidden=false;form.elements.username.focus();};
  auth.querySelector('.intro-guest').onclick=close;auth.querySelector('.intro-show-password').onclick=event=>{const input=form.elements.password;input.type=input.type==='password'?'text':'password';event.currentTarget.textContent=input.type==='password'?'Show':'Hide';};auth.querySelector('.intro-switch').onclick=event=>{mode=mode==='login'?'signup':'login';form.querySelector('[type=submit]').textContent=mode==='login'?'Log in':'Create account';event.currentTarget.textContent=mode==='login'?'Create an account':'Already have an account? Log in';form.elements.password.autocomplete=mode==='login'?'current-password':'new-password';error.textContent='';};
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;error.textContent='';try{const response=await fetch('/api/auth/'+mode,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:form.elements.username.value.trim(),password:form.elements.password.value})});await readAccountResponse(response);sessionStorage.setItem('fieldshift.session.verified','1');sessionStorage.setItem('fieldshift.intro.skip-auto','1');location.hash='/overview';location.reload();}catch(problem){error.textContent=problem instanceof TypeError?'The account server is unavailable. Run the complete FieldShift project with npm run dev, then open http://localhost:4173.':problem.message||'Unable to sign in.';button.disabled=false;}};
  row.querySelector('button').onclick=open;overlay.addEventListener('keydown',event=>{if(event.key==='Escape')close();});window.addEventListener('fieldshift:language',event=>{current=copy[event.detail]?event.detail:'en';apply();});apply();if(!sessionStorage.getItem('fieldshift.intro.skip-auto'))requestAnimationFrame(open);else {overlay.hidden=true;document.body.classList.remove('intro-pending');}return{open};
}
